import{_ as t,c as a,a2 as l,o as n}from"./chunks/framework.BnrAgU0Y.js";const h=JSON.parse('{"title":"遥测","description":"遥测","frontmatter":{"title":"遥测","description":"遥测","layout":"doc"},"headers":[],"relativePath":"langflow/contributing-telemetry.md","filePath":"langflow/contributing-telemetry.md"}'),r={name:"langflow/contributing-telemetry.md"};function e(i,o,s,g,c,u){return n(),a("div",null,o[0]||(o[0]=[l('<h1 id="遥测" tabindex="-1">遥测 <a class="header-anchor" href="#遥测" aria-label="Permalink to &quot;遥测&quot;">​</a></h1><p>Langflow 使用匿名遥测来收集基本的使用统计数据，以增强功能和用户体验。这些数据帮助我们识别受欢迎的功能和需要改进的领域，并确保开发工作与您的需求保持一致。</p><p>我们尊重您的隐私，并致力于保护您的数据。我们不会收集任何个人信息或敏感数据。所有遥测数据都是匿名化的，仅用于改进 Langflow。</p><h2 id="选择退出遥测数据" tabindex="-1">选择退出遥测数据 <a class="header-anchor" href="#选择退出遥测数据" aria-label="Permalink to &quot;选择退出遥测数据&quot;">​</a></h2><p>要选择退出遥测数据收集，在运行 Langflow 之前，设置环境变量 <code>LANGFLOW_DO_NOT_TRACK</code> 或 <code>DO_NOT_TRACK</code> 为 <code>true</code>。这样可以禁用遥测数据的收集。</p><h2 id="langflow-收集的数据" tabindex="-1">Langflow 收集的数据 <a class="header-anchor" href="#langflow-收集的数据" aria-label="Permalink to &quot;Langflow 收集的数据&quot;">​</a></h2><h3 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h3><ul><li><strong>IsWebhook</strong>: 指示操作是否通过 webhook（网络钩子）触发。</li><li><strong>Seconds</strong>: 操作持续的时间，单位为秒，用于提供性能方面的见解。</li><li><strong>Success</strong>: 布尔值，指示操作是否成功，有助于识别潜在的错误或问题。</li><li><strong>ErrorMessage</strong>: 在操作不成功时提供错误信息的详细说明，有助于故障排除和改进。</li></ul><h3 id="停机" tabindex="-1">停机 <a class="header-anchor" href="#停机" aria-label="Permalink to &quot;停机&quot;">​</a></h3><ul><li><strong>运行时间</strong>: 停机前的总运行时间，对于了解应用程序生命周期和优化正常运行时间很有用。</li></ul><h3 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h3><ul><li><strong>版本</strong>: Langflow 使用的具体版本，有助于跟踪功能采纳和兼容性。</li><li><strong>平台</strong>: 主机机器的操作系统，帮助我们专注支持像 Windows、macOS 和 Linux 这样的热门平台。</li><li><strong>Python</strong>: 使用的 Python 版本，协助维持对不同 Python 版本的兼容性和支持。</li><li><strong>架构</strong>: 系统的架构（例如，x86，ARM），有助于针对不同硬件优化我们的软件。</li><li><strong>自动登录</strong>: 指示自动登录功能是否启用，反映用户的偏好设置。</li><li><strong>缓存类型</strong>: 使用的缓存机制类型，影响性能和效率。</li><li><strong>仅后端</strong>: 布尔值，指示您是否在仅后端模式下运行 Langflow，对理解部署配置有帮助。</li></ul><h3 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h3><ul><li><strong>Seconds</strong>: Playground 执行的持续时间（以秒为单位），用于提供测试或实验阶段的性能见解。</li><li><strong>ComponentCount</strong>: 在 Playground 中使用的组件数量，有助于了解复杂性和使用模式。</li><li><strong>Success</strong>: Playground 操作的成功状态，有助于识别实验性功能的稳定性。</li></ul><h3 id="组件" tabindex="-1">组件 <a href="#630728d6654c40a6b8901459a4bc3a4e" class="hash-link" aria-label="Direct link to Component" title="Direct link to Component"></a> <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件 &lt;a href=&quot;#630728d6654c40a6b8901459a4bc3a4e&quot; class=&quot;hash-link&quot; aria-label=&quot;Direct link to Component&quot; title=&quot;Direct link to Component&quot;&gt;&lt;/a&gt;&quot;">​</a></h3><ul><li><strong>名称</strong>: 识别组件，提供哪些组件使用最多或容易出现问题的数据。</li><li><strong>秒数</strong>: 组件执行所花费的时间，提供性能指标。</li><li><strong>成功</strong>: 组件是否成功运行，有助于质量控制。</li><li><strong>错误信息</strong>: 遇到的任何错误的详细信息，对于调试和改进至关重要。</li></ul>',16)]))}const f=t(r,[["render",e]]);export{h as __pageData,f as default};
